package com.nstut.biotech.jei;

import com.nstut.biotech.Biotech;import com.nstut.biotech.machines.MachineRegistries;import com.nstut.biotech.recipes.MixerRecipe;import mezz.jei.api.constants.VanillaTypes;import mezz.jei.api.gui.builder.IRecipeLayoutBuilder;import mezz.jei.api.gui.drawable.IDrawable;import mezz.jei.api.gui.ingredient.IRecipeSlotsView;import mezz.jei.api.helpers.IGuiHelper;import mezz.jei.api.recipe.IFocusGroup;import mezz.jei.api.recipe.RecipeIngredientRole;import mezz.jei.api.recipe.RecipeType;import mezz.jei.api.recipe.category.IRecipeCategory;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.network.chat.Component;import net.minecraft.resources.Identifier;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.crafting.Ingredient;import net.neoforged.neoforge.fluids.FluidStack;import org.jetbrains.annotations.NotNull;import java.util.List;
public class MixerCategory implements IRecipeCategory<MixerRecipe>{public static final Identifier UID=Identifier.fromNamespaceAndPath(Biotech.MOD_ID,MachineRegistries.MIXER.id());public static final Identifier TEXTURE=Identifier.fromNamespaceAndPath(Biotech.MOD_ID,"textures/gui/jei/"+MachineRegistries.MIXER.id()+".png");public static final RecipeType<MixerRecipe> TYPE=new RecipeType<>(UID,MixerRecipe.class);private final IDrawable background,icon;public MixerCategory(IGuiHelper h){background=h.createDrawable(TEXTURE,0,0,129,69);icon=h.createDrawableIngredient(VanillaTypes.ITEM_STACK,new ItemStack(MachineRegistries.MIXER.blockItem().get()));}@Override public @NotNull RecipeType<MixerRecipe> getRecipeType(){return TYPE;}@Override public @NotNull Component getTitle(){return Component.translatable("block.biotech."+MachineRegistries.MIXER.id());}@Override public int getWidth(){return background.getWidth();}@Override public int getHeight(){return background.getHeight();}@Override public @NotNull IDrawable getIcon(){return icon;}@Override public void setRecipe(@NotNull IRecipeLayoutBuilder b,@NotNull MixerRecipe r,@NotNull IFocusGroup f){List<ItemStack> i=r.getItemIngredients().stream().map(v->v.getItemStack()).toList();List<ItemStack> o=r.getItemOutputs().stream().map(v->v.getItemStack()).toList();for(int n=0;n<i.size();n++)b.addSlot(RecipeIngredientRole.INPUT,23+(n%3)*18,1+(n/3)*18).addItemStack(i.get(n));for(int n=0;n<r.getFluidIngredients().size();n++){FluidStack fl=r.getFluidIngredients().get(n);b.addSlot(RecipeIngredientRole.INPUT,23+18*n,38).addFluidStack(fl.getFluid(),fl.getAmount()).setFluidRenderer(fl.getAmount(),false,16,16);}b.addSlot(RecipeIngredientRole.OUTPUT,112,9).addItemStack(o.get(0));if(!r.getFluidOutputs().isEmpty())b.addSlot(RecipeIngredientRole.OUTPUT,112,27).addFluidStack(r.getFluidOutputs().get(0).getFluid(),r.getFluidOutputs().get(0).getAmount()).setFluidRenderer(r.getFluidOutputs().get(0).getAmount(),false,16,16);}@Override public void draw(MixerRecipe r,@NotNull IRecipeSlotsView s,GuiGraphicsExtractor g,double x,double y){background.draw(g);g.text(Minecraft.getInstance().font,"Energy: "+r.getTotalEnergy()+" FE",0,59,4210752,false);}}
